package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_22_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a fraction with numerator 0 and denominator 5
        Fraction fraction = Fraction.getFraction(0, 5);

        // The fraction should be simplified to 0/1
        assertEquals("Fraction should be simplified to 0/1", Fraction.ZERO, fraction);
    }
}

